def extend_pattern(pattern8, n):
    if n <= 8:
        return pattern8[:n]
    ob = 1 if pattern8[0] == 1 else pattern8[7]
    period = pattern8[:7]
    fingers = []
    for i in range(n - 1):
        fingers.append(ob if (i > 0 and i % 7 == 0) else period[i % 7])
    fingers.append(pattern8[7])
    return fingers


@pytest.fixture(scope="module")
def fixture_data():
    with open(FIXTURE) as f:
        return json.load(f)


def _cases(fixture_data):
    for group_name in ("group1", "group2", "group3"):
        g = fixture_data[group_name]
        for key in g["keys"]:
            yield key, g["rightHand"], g["leftHand"]


